const graph = {"nodes":[{"id":"core/model/define-capability-format","title":"Define capability format","label":"Define capability format","area":"core","status":"implemented","impact":6,"gaps":0,"r":68,"x":170,"y":170},{"id":"core/graph/compile-capabilities","title":"Compile capabilities","label":"Compile capabilities","area":"core","status":"implemented","impact":5,"gaps":0,"r":63,"x":170,"y":170},{"id":"core/validation/validate-capability-files","title":"Validate capability files","label":"Validate capability files","area":"core","status":"implemented","impact":4,"gaps":0,"r":58,"x":170,"y":170},{"id":"core/agents/prepare-agent-task-bundle","title":"Prepare agent task bundle","label":"Prepare agent task bundle","area":"core","status":"implemented","impact":2,"gaps":0,"r":48,"x":194,"y":288},{"id":"core/validation/verify-implementation-references","title":"Verify implementation references","label":"Verify implementation refe...","area":"core","status":"implemented","impact":2,"gaps":0,"r":48,"x":194,"y":288},{"id":"core/agents/review-capability-with-agent","title":"Review capability with agent","label":"Review capability with agent","area":"core","status":"implemented","impact":1,"gaps":1,"r":46,"x":194,"y":288},{"id":"core/assessment/assess-implementation-coverage","title":"Assess implementation coverage","label":"Assess implementation cove...","area":"core","status":"implemented","impact":1,"gaps":0,"r":43,"x":170,"y":406},{"id":"core/graph/analyze-capability-impact","title":"Analyze capability impact","label":"Analyze capability impact","area":"core","status":"implemented","impact":1,"gaps":0,"r":43,"x":170,"y":406},{"id":"core/project/initialize-capability-project","title":"Initialize capability project","label":"Initialize capability proj...","area":"core","status":"implemented","impact":1,"gaps":0,"r":43,"x":170,"y":406},{"id":"developer-experience/cli/cli-workflow","title":"CLI workflow","label":"CLI workflow","area":"developer-experience","status":"implemented","impact":1,"gaps":0,"r":43,"x":744,"y":524},{"id":"docs/reference/capability-format-documentation","title":"Capability format documentation","label":"Capability format document...","area":"docs","status":"implemented","impact":1,"gaps":0,"r":43,"x":1294,"y":524},{"id":"core/agents/ingest-agent-review-result","title":"Ingest agent review result","label":"Ingest agent review result","area":"core","status":"implemented","impact":0,"gaps":0,"r":38,"x":194,"y":524},{"id":"core/agents/run-external-agent-cli","title":"Run external agent CLI","label":"Run external agent CLI","area":"core","status":"implemented","impact":0,"gaps":0,"r":38,"x":170,"y":642},{"id":"core/graph/diff-capabilities","title":"Diff capabilities","label":"Diff capabilities","area":"core","status":"implemented","impact":0,"gaps":0,"r":38,"x":170,"y":642},{"id":"core/validation/detect-verification-gaps","title":"Detect verification gaps","label":"Detect verification gaps","area":"core","status":"implemented","impact":0,"gaps":0,"r":38,"x":170,"y":642},{"id":"developer-experience/examples/example-project","title":"Example project","label":"Example project","area":"developer-experience","status":"implemented","impact":0,"gaps":0,"r":38,"x":744,"y":760},{"id":"developer-experience/integrations/vs-code-extension-readiness","title":"VS Code extension readiness","label":"VS Code extension readiness","area":"developer-experience","status":"planned","impact":0,"gaps":0,"r":38,"x":744,"y":760},{"id":"developer-experience/skills/install-capabilitykit-skill","title":"Install CapabilityKit skill","label":"Install CapabilityKit skill","area":"developer-experience","status":"implemented","impact":0,"gaps":0,"r":38,"x":744,"y":760},{"id":"docs/project/readme","title":"README","label":"README","area":"docs","status":"implemented","impact":0,"gaps":0,"r":38,"x":1270,"y":878}],"links":[{"source":"core/model/define-capability-format","target":"core/graph/compile-capabilities"},{"source":"core/validation/validate-capability-files","target":"core/graph/compile-capabilities"},{"source":"core/model/define-capability-format","target":"core/validation/validate-capability-files"},{"source":"core/graph/compile-capabilities","target":"core/agents/prepare-agent-task-bundle"},{"source":"core/validation/verify-implementation-references","target":"core/agents/prepare-agent-task-bundle"},{"source":"core/validation/validate-capability-files","target":"core/validation/verify-implementation-references"},{"source":"core/agents/prepare-agent-task-bundle","target":"core/agents/review-capability-with-agent"},{"source":"core/assessment/assess-implementation-coverage","target":"core/agents/review-capability-with-agent"},{"source":"core/validation/verify-implementation-references","target":"core/assessment/assess-implementation-coverage"},{"source":"core/graph/compile-capabilities","target":"core/graph/analyze-capability-impact"},{"source":"core/validation/validate-capability-files","target":"core/graph/analyze-capability-impact"},{"source":"core/model/define-capability-format","target":"core/project/initialize-capability-project"},{"source":"core/project/initialize-capability-project","target":"developer-experience/cli/cli-workflow"},{"source":"core/validation/validate-capability-files","target":"developer-experience/cli/cli-workflow"},{"source":"core/graph/compile-capabilities","target":"developer-experience/cli/cli-workflow"},{"source":"core/model/define-capability-format","target":"docs/reference/capability-format-documentation"},{"source":"core/agents/review-capability-with-agent","target":"core/agents/ingest-agent-review-result"},{"source":"core/agents/prepare-agent-task-bundle","target":"core/agents/run-external-agent-cli"},{"source":"core/graph/compile-capabilities","target":"core/graph/diff-capabilities"},{"source":"core/graph/analyze-capability-impact","target":"core/graph/diff-capabilities"},{"source":"core/model/define-capability-format","target":"core/validation/detect-verification-gaps"},{"source":"core/model/define-capability-format","target":"developer-experience/examples/example-project"},{"source":"core/graph/compile-capabilities","target":"developer-experience/integrations/vs-code-extension-readiness"},{"source":"developer-experience/cli/cli-workflow","target":"developer-experience/skills/install-capabilitykit-skill"},{"source":"docs/reference/capability-format-documentation","target":"docs/project/readme"}]};
const width = 1440;
const height = 980;
const padding = 74;
const graphLayer = document.getElementById("graph");
const linksLayer = document.getElementById("links");
const nodesLayer = document.getElementById("nodes");
const details = document.getElementById("details");
const detailTitle = document.getElementById("detail-title");
const detailStatus = document.getElementById("detail-status");
const detailImpact = document.getElementById("detail-impact");
const zoomValue = document.getElementById("zoom-value");
const zoomFill = document.getElementById("zoom-fill");
const zoomKnob = document.getElementById("zoom-knob");
const forceValue = document.getElementById("force-value");
const forceFill = document.getElementById("force-fill");
const forceKnob = document.getElementById("force-knob");
const byId = new Map(graph.nodes.map((node) => [node.id, node]));
const links = graph.links
  .map((link) => ({ source: byId.get(link.source), target: byId.get(link.target) }))
  .filter((link) => link.source && link.target);
const linked = new Set();
for (const link of links) {
  linked.add(link.source.id + "->" + link.target.id);
  linked.add(link.target.id + "->" + link.source.id);
}
const statusClass = (node) => node.gaps > 0 ? "gap" : node.status === "planned" ? "planned" : node.status === "in-progress" ? "review" : "implemented";
function el(name, attrs = {}) {
  const node = document.createElementNS("http://www.w3.org/2000/svg", name);
  for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, String(value));
  return node;
}
const linkEls = links.map((link) => {
  const path = el("path", { class: "link" });
  linksLayer.appendChild(path);
  return { ...link, el: path };
});
const nodeEls = graph.nodes.map((node) => {
  node.vx = 0;
  node.vy = 0;
  const group = el("g", { class: "node " + statusClass(node), tabindex: "0" });
  group.appendChild(el("circle", { class: "node-halo", r: node.r + 8 }));
  group.appendChild(el("circle", { class: "node-ring", r: node.r }));
  group.appendChild(el("circle", { class: "node-core", r: Math.max(node.r - 10, 20) }));
  const label = el("text", { class: "label", y: "-3" });
  const words = node.label.split(" ");
  if (words.length > 2) {
    const first = el("tspan", { x: 0, dy: "-3" });
    first.textContent = words.slice(0, Math.ceil(words.length / 2)).join(" ");
    const second = el("tspan", { x: 0, dy: "14" });
    second.textContent = words.slice(Math.ceil(words.length / 2)).join(" ");
    label.append(first, second);
  } else {
    label.textContent = node.label;
  }
  const meta = el("text", { class: "meta", y: node.r - 12 });
  meta.textContent = node.area;
  group.append(label, meta);
  group.addEventListener("pointerdown", (event) => startDrag(event, node, group));
  group.addEventListener("pointerenter", () => highlight(node));
  group.addEventListener("pointerleave", clearHighlight);
  group.addEventListener("focus", () => highlight(node));
  group.addEventListener("blur", clearHighlight);
  nodesLayer.appendChild(group);
  return { node, el: group };
});
let alpha = 1;
let dragging = null;
let frameId = 0;
let zoomLevel = 1;
let forceScale = 1.25;
function sliderX(value, min, max) {
  return ((value - min) / (max - min)) * 202;
}
function applyZoom() {
  const tx = width / 2 - (width / 2) * zoomLevel;
  const ty = height / 2 - (height / 2) * zoomLevel;
  graphLayer.setAttribute("transform", "translate(" + tx.toFixed(1) + " " + ty.toFixed(1) + ") scale(" + zoomLevel.toFixed(3) + ")");
  zoomValue.textContent = Math.round(zoomLevel * 100) + "%";
  const x = sliderX(zoomLevel, 0.72, 1.38);
  zoomFill.setAttribute("x2", x.toFixed(1));
  zoomKnob.setAttribute("cx", x.toFixed(1));
}
function applyForceControl() {
  forceValue.textContent = Math.round(forceScale * 100) + "%";
  const x = sliderX(forceScale, 0.9, 1.7);
  forceFill.setAttribute("x2", x.toFixed(1));
  forceKnob.setAttribute("cx", x.toFixed(1));
}
function attachSlider(knob, min, max, current, onChange) {
  const trackStart = 0;
  const trackWidth = 202;
  knob.addEventListener("pointerdown", (event) => {
    event.preventDefault();
    knob.setPointerCapture(event.pointerId);
    const slider = knob.closest(".slider");
    const matrix = slider.getScreenCTM().inverse();
    const update = (moveEvent) => {
      const point = document.documentElement.createSVGPoint();
      point.x = moveEvent.clientX;
      point.y = moveEvent.clientY;
      const local = point.matrixTransform(matrix);
      const clamped = Math.max(trackStart, Math.min(trackWidth, local.x));
      const value = min + (clamped / trackWidth) * (max - min);
      onChange(value);
    };
    const stop = () => {
      knob.removeEventListener("pointermove", update);
      knob.removeEventListener("pointerup", stop);
      knob.removeEventListener("pointercancel", stop);
    };
    update(event);
    knob.addEventListener("pointermove", update);
    knob.addEventListener("pointerup", stop);
    knob.addEventListener("pointercancel", stop);
  });
  onChange(current);
}
function forceTick() {
  for (const node of graph.nodes) {
    node.vx += (width / 2 - node.x) * 0.0009 * alpha;
    node.vy += (height / 2 + 18 - node.y) * 0.0009 * alpha;
  }
  for (const link of links) {
    const dx = link.target.x - link.source.x;
    const dy = link.target.y - link.source.y;
    const distance = Math.hypot(dx, dy) || 1;
    const targetDistance = (210 + Math.max(link.source.r, link.target.r) * 0.55) * forceScale;
    const strength = (distance - targetDistance) * 0.012 * alpha;
    const fx = (dx / distance) * strength;
    const fy = (dy / distance) * strength;
    if (!link.source.fixed) {
      link.source.vx += fx;
      link.source.vy += fy;
    }
    if (!link.target.fixed) {
      link.target.vx -= fx;
      link.target.vy -= fy;
    }
  }
  for (let i = 0; i < graph.nodes.length; i++) {
    for (let j = i + 1; j < graph.nodes.length; j++) {
      const a = graph.nodes[i];
      const b = graph.nodes[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const distance = Math.hypot(dx, dy) || 1;
      const minDistance = (a.r + b.r + 46) * forceScale;
      const repulsion = Math.min((15000 * forceScale) / (distance * distance), 2.4) * alpha;
      const nx = dx / distance;
      const ny = dy / distance;
      if (!a.fixed) {
        a.vx -= nx * repulsion;
        a.vy -= ny * repulsion;
      }
      if (!b.fixed) {
        b.vx += nx * repulsion;
        b.vy += ny * repulsion;
      }
      if (distance < minDistance) {
        const push = ((minDistance - distance) / distance) * 0.55;
        if (!a.fixed) {
          a.x -= dx * push;
          a.y -= dy * push;
        }
        if (!b.fixed) {
          b.x += dx * push;
          b.y += dy * push;
        }
      }
    }
  }
  for (const node of graph.nodes) {
    if (!node.fixed) {
      node.vx *= 0.78;
      node.vy *= 0.78;
      node.x += node.vx;
      node.y += node.vy;
    }
    node.x = Math.max(padding + node.r, Math.min(width - padding - node.r, node.x));
    node.y = Math.max(118 + node.r, Math.min(height - padding - node.r, node.y));
  }
  alpha = dragging ? Math.max(alpha * 0.96, 0.34) : alpha * 0.972;
}
function render() {
  for (const link of linkEls) {
    const dx = link.target.x - link.source.x;
    const dy = link.target.y - link.source.y;
    const distance = Math.hypot(dx, dy) || 1;
    const sx = link.source.x + (dx / distance) * (link.source.r + 7);
    const sy = link.source.y + (dy / distance) * (link.source.r + 7);
    const tx = link.target.x - (dx / distance) * (link.target.r + 11);
    const ty = link.target.y - (dy / distance) * (link.target.r + 11);
    const curve = Math.min(90, distance * 0.18);
    const mx = (sx + tx) / 2 - (dy / distance) * curve;
    const my = (sy + ty) / 2 + (dx / distance) * curve;
    link.el.setAttribute("d", "M" + sx.toFixed(1) + "," + sy.toFixed(1) + " Q" + mx.toFixed(1) + "," + my.toFixed(1) + " " + tx.toFixed(1) + "," + ty.toFixed(1));
  }
  for (const item of nodeEls) {
    item.el.setAttribute("transform", "translate(" + item.node.x.toFixed(1) + " " + item.node.y.toFixed(1) + ")");
  }
}
function animate() {
  for (let i = 0; i < 4; i++) forceTick();
  render();
  const maxVelocity = graph.nodes.reduce((max, node) => Math.max(max, Math.abs(node.vx) + Math.abs(node.vy)), 0);
  if (!dragging && alpha < 0.016 && maxVelocity < 0.05) {
    for (const node of graph.nodes) {
      node.vx = 0;
      node.vy = 0;
    }
    alpha = 0;
    frameId = 0;
    render();
    return;
  }
  frameId = requestAnimationFrame(animate);
}
function restartSimulation(nextAlpha = 0.7) {
  alpha = Math.max(alpha, nextAlpha);
  if (!frameId) frameId = requestAnimationFrame(animate);
}
attachSlider(zoomKnob, 0.72, 1.38, zoomLevel, (value) => {
  zoomLevel = value;
  applyZoom();
});
attachSlider(forceKnob, 0.9, 1.7, forceScale, (value) => {
  forceScale = value;
  applyForceControl();
  restartSimulation(0.85);
});
function svgPoint(event) {
  const svg = event.currentTarget.ownerSVGElement || document.documentElement;
  const point = svg.createSVGPoint();
  point.x = event.clientX;
  point.y = event.clientY;
  return point.matrixTransform(graphLayer.getScreenCTM().inverse());
}
function startDrag(event, node, group) {
  event.preventDefault();
  group.setPointerCapture(event.pointerId);
  dragging = node;
  node.fixed = true;
  restartSimulation(0.75);
  const move = (moveEvent) => {
    const point = svgPoint(moveEvent);
    node.x = point.x;
    node.y = point.y;
    node.vx = 0;
    node.vy = 0;
    render();
  };
  const up = () => {
    node.fixed = false;
    dragging = null;
    group.removeEventListener("pointermove", move);
    group.removeEventListener("pointerup", up);
    group.removeEventListener("pointercancel", up);
  };
  group.addEventListener("pointermove", move);
  group.addEventListener("pointerup", up);
  group.addEventListener("pointercancel", up);
}
function highlight(node) {
  const cardWidth = 520;
  const cardHeight = 106;
  const visualX = width / 2 + (node.x - width / 2) * zoomLevel;
  const visualY = height / 2 + (node.y - height / 2) * zoomLevel;
  const visualR = node.r * zoomLevel;
  const x = Math.max(28, Math.min(width - cardWidth - 28, visualX + visualR + 22));
  const preferredY = visualY + visualR + 18;
  const fallbackY = visualY - visualR - cardHeight - 18;
  const y = preferredY + cardHeight < height - 34 ? preferredY : Math.max(104, fallbackY);
  details.setAttribute("transform", "translate(" + x.toFixed(1) + " " + y.toFixed(1) + ")");
  details.setAttribute("opacity", "1");
  detailTitle.textContent = node.title;
  detailStatus.textContent = node.id + " | " + node.status + " | " + node.area;
  detailImpact.textContent = "Direct dependents: " + node.impact + " | verification gaps: " + node.gaps;
  for (const item of nodeEls) {
    const connected = item.node.id === node.id || linked.has(item.node.id + "->" + node.id);
    item.el.classList.toggle("dimmed", !connected);
  }
  for (const link of linkEls) {
    const active = link.source.id === node.id || link.target.id === node.id;
    link.el.classList.toggle("active", active);
    link.el.classList.toggle("dimmed", !active);
  }
}
function clearHighlight() {
  details.setAttribute("opacity", "0");
  for (const item of nodeEls) item.el.classList.remove("dimmed");
  for (const link of linkEls) link.el.classList.remove("active", "dimmed");
}
restartSimulation(1);
